with filtered as (select *, datediff(current_date(), reading_ts) days_since_reading_ts, humidity * temp_c humidity_times_temp_c from device_readings where reading_ts >= date '2025-09-01') select id, reading_ts, temp_c, pressure, status_bits, days_since_reading_ts, humidity_times_temp_c, max(humidity) over (partition by device_code order by temp_c, id rows between 2 preceding and current row) last3_max_humidity, min(humidity) over (partition by device_code order by temp_c, id rows between 2 preceding and current row) last3_min_humidity, avg(humidity) over (partition by device_code order by temp_c, id rows between 2 preceding and current row) last3_avg_humidity, row_number() over (order by pressure desc, id) row_seq from filtered
